 function nextRankXp(){return state.experience<40?40:state.experience<90?90:state.experience<180?180:state.experience<300?300:500}
 function matchesFilter(id){if(currentFilter==='owned')return state.holdings.includes(id);if(currentFilter==='conflict')return places[id].owner==='Red Crown'||places[id].owner==='High King';return true}
 function isAdjacent(id){return state.holdings.some(h=>places[h].adj.includes(id))}
 function addEvent(text,when='THIS SEASON'){state.events.unshift({text,when});state.events=state.events.slice(0,8)}

input.newString:
function processAI(){if(Math.random()>.3)return;let candidates=Object.keys(places).filter(id=>!state.holdings.includes(id));let target=candidates[Math.floor(Math.random()*candidates.length)];if(!target)return;let neighbors=places[target].adj.filter(id=>!state.holdings.includes(id)&&places[id].owner!==places[target].owner);if(neighbors.length){let source=places[neighbors[Math.floor(Math.random()*neighbors.length)]];if(Math.random()<.55){let old=places[target].owner;places[target].owner=source.owner;places[target].troops=Math.max(45,Math.floor(places[target].troops*.72));addEvent(`${source.owner} forces seized ${places[target].name} from ${old}; the border kingdoms stir.`,'WORLD NEWS')}else if(Math.random()<.2){addEvent(`An uneasy truce was signed between rival courts near ${places[target].name}.`,'WORLD NEWS')}}if(Math.random()<.08){let id=state.holdings[Math.floor(Math.random()*state.holdings.length)];if(id&&state.army>80){state.army-=12;state.loyalty=Math.max(35,state.loyalty-2);addEvent(`A rival raid struck the outskirts of ${places[id].name}; 12 soldiers were lost.`,'BORDER ALERT')}}}
function succession(){let old=state.first;if(state.children>0){state.children--;state.first=['Rowan','Mira','Tarin','Elowen','Soren'][Math.floor(Math.random()*5)];state.age=18;state.experience=Math.floor(state.experience*.72);state.army=Math.floor(state.army*.82);state.loyalty=Math.max(45,state.loyalty-8);addEvent(`${old} ${state.surname} died peacefully. Heir ${state.first} inherits the dynasty and its burdens.`,'A GENERATION PASSES');toast(`A new generation rises: ${state.first} ${state.surname}.`)}else{state.first='House Heir';state.age=18;state.experience=Math.floor(state.experience*.5);state.army=Math.floor(state.army*.65);state.loyalty=Math.max(30,state.loyalty-18);addEvent(`${old} ${state.surname} died without an heir. A distant cousin takes the name amid a succession crisis.`,'A GENERATION PASSES');toast('A distant heir inherits a fractured realm.')}}
function advanceSeason(){state.season++;let income=state.holdings.reduce((n,id)=>n+places[id].wealth,0);state.gold+=income;state.food+=Math.max(8,state.holdings.length*12)-Math.ceil(state.army/90);if(state.food<0){state.food=0;state.loyalty=Math.max(10,state.loyalty-4);state.army=Math.max(30,state.army-10);addEvent('Famine in the camps weakened your forces.','THIS SEASON')}else state.loyalty=Math.min(100,state.loyalty+1);state.influence+=state.holdings.length>1?2:1;if(state.season%4===0){state.renown+=2;state.age=(state.age||18)+1}if(Math.random()<.24){let texts=['The High King convenes the royal council at Highcourt.','Caravans report border skirmishes near Amberhold.','A harvest festival brings new confidence to your lands.','A rival lord quietly gathers support among the western nobles.','Your heralds carry news of a changing tide across the continents.'];let text=texts[Math.floor(Math.random()*texts.length)];addEvent(text,`${seasonName().toUpperCase()} ${year()}`)}if(state.season%5===0&&state.holdings.length>1){let id=state.holdings[Math.floor(Math.random()*state.holdings.length)];places[id].loyalty=Math.max(40,(places[id].loyalty||70)-3);addEvent(`Whispers of unrest in ${places[id].name}. A governor could steady the province.`)}processAI();if(state.age>=68&&Math.random()<.035)succession();render();toast(`${seasonName()} ${year()} · +${income} gold from your realm`)}

