function petition(type){let cost=type==='tax'?4:6;if(state.influence<cost)return toast('You lack the influence to petition the crown.');state.influence-=cost;if(type==='tax'){state.loyalty=Math.min(100,state.loyalty+9);addEvent('The King granted a temporary tax reprieve to your people.');toast('Your petition was granted. Loyalty rises.')}else{state.experience+=15;state.renown+=5;addEvent(`The King granted ${state.first} ${state.surname} a noble title.`);toast('A title at court raises your standing.')}render()}
function declareIndependence(){if(state.holdings.length<3||state.army<400)return toast('Independence requires 3 holdings and 400 soldiers. Build strength first.');if(!confirm('Defy the High King? The realm will become your enemy.'))return;places.highcourt.owner='Your enemy';state.influence+=10;state.renown+=20;addEvent(`${state.first} ${state.surname} declared independence from the High King!`);toast('The rebellion begins!');render()}
function seekMatch(){if(state.married){state.children++;state.experience+=5;addEvent(`A child was born into House ${state.surname}; their future awaits your guidance.`);toast(`A new heir carries the name ${state.surname}.`)}else{state.married=true;state.loyalty=Math.min(100,state.loyalty+4);state.influence+=2;addEvent(`A diplomatic marriage binds House ${state.surname} to a noble family.`);toast('A royal match strengthens your dynasty.')}render()}
render();
</script>

