const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const browser=await chromium.launch({headless:true});for(const width of [320,390]){const page=await browser.newPage({viewport:{width,height:844}});await page.goto('http://localhost:3002');await page.evaluate(()=>localStorage.removeItem('fatebearer-save'));await page.reload();const report=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth,topbar:Math.round(document.querySelector('.topbar').getBoundingClientRect().width),date:document.querySelector('.date-chip').getBoundingClientRect().toJSON(),newButton:document.querySelector('#newGameBtn').getBoundingClientRect().toJSON(),buttonText:document.querySelector('#newGameBtn').innerText}));for(const view of ['army','realm','council','dynasty','map']){await page.locator(`[data-view=${view}]`).click();const over=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);if(over)throw new Error(`${width}px horizontal overflow in ${view}`)}console.log(JSON.stringify(report));await page.close()}await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
