import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true});
for(const width of [320,390,1050]) {
 const page=await browser.newPage({viewport:{width,height:900}}); await page.goto('http://127.0.0.1:8765');
 for(const view of ['map','army','realm','council','dynasty']) {
  await page.locator(`.nav-btn[data-view="${view}"]`).click();
  const d=await page.evaluate(()=>({vw:innerWidth,sw:document.documentElement.scrollWidth,bw:document.body.scrollWidth,offenders:[...document.querySelectorAll('body *')].map(e=>({tag:e.tagName,cls:typeof e.className==='string'?e.className:'',id:e.id,right:Math.round(e.getBoundingClientRect().right)})).filter(e=>e.right>innerWidth+1).slice(0,8)}));
  if(d.sw>width||d.bw>width) console.log(width,view,JSON.stringify(d));
 }
 await page.close();
}
await browser.close();
