node --input-type=module - <<'NODE'
import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
mkdirSync('screenshots',{recursive:true});
const browser=await chromium.launch({headless:true});
for(const [name,width,height] of [['fatebearer-review',1050,900],['fatebearer-mobile',390,844],['fatebearer-narrow',320,900]]){
 const page=await browser.newPage({viewport:{width,height},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8765',{waitUntil:'networkidle'});
 await page.evaluate(()=>document.fonts.ready);
 const dims=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,height:innerHeight}));
 if(dims.width!==width||dims.scrollWidth>width) throw new Error(`${name} overflow: ${JSON.stringify(dims)}`);
 await page.screenshot({path:`screenshots/${name}.jpg`,type:'jpeg',quality:90});
 if(errors.length) throw new Error(`${name} JS errors: ${errors.join('; ')}`);
 console.log(`${name}: ${JSON.stringify(dims)}, saved JPEG`);
 await page.close();
}
await browser.close();
NODE
